use crate::model::Summary;

fn checksum(data: &[u8]) -> u8 {
    data.iter().fold(0u8, |sum, byte| sum.wrapping_add(*byte))
}

pub fn run(data: &[u8], limit: i64) -> Summary {
    let mut frames = Vec::new();
    let mut cursor = 0usize;
    let mut error = 0i64;

    while cursor < data.len() {
        let header = data[cursor];
        if header == 255 {
            cursor += 1;
            continue;
        }

        let (length, payload_start) = if header == 254 {
            if data.len() - cursor < 3 {
                error = 1;
                break;
            }
            (u16::from_le_bytes([data[cursor + 1], data[cursor + 2]]) as usize, cursor + 3)
        } else {
            (header as usize, cursor + 1)
        };

        if (length as i64) > limit {
            error = 3;
            break;
        }
        if data.len() - payload_start < length + 1 {
            error = 1;
            break;
        }

        let payload_end = payload_start + length;
        let payload = &data[payload_start..payload_end];
        if checksum(payload) != data[payload_end] {
            error = 2;
            break;
        }
        frames.push(payload.to_vec());
        cursor = payload_end + 1;
    }

    Summary {
        frames,
        consumed: if error == 0 { data.len() as i64 } else { cursor as i64 },
        error,
    }
}

